#include "document/PartDocument.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <BRepGProp.hxx>
#include <GProp_GProps.hxx>
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace thecad::modeling;using namespace thecad::document;
namespace {
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
void near(double a,double b){check(std::abs(a-b)<1e-6,"Unexpected associative coordinate");}
template<class F>void rejects(F action){bool rejected=false;try{action();}catch(const std::exception&){rejected=true;}check(rejected,"Ambiguous/invalid definition was accepted");}
GeometryReference datum(const std::string& id){GeometryReference r;r.source=ReferenceSource::Datum;r.featureId=id;return r;}
GeometryReference plane(int i){GeometryReference r;r.source=ReferenceSource::BasePlane;r.index=i;return r;}
std::string make(PartDocument& doc,DatumMethod m,std::vector<GeometryReference> refs,double value=0){DatumDefinition d;d.method=m;d.references=std::move(refs);d.value=value;return doc.addReferenceGeometry(d);}
Feature feature(const PartDocument& d,const std::string& id){return *std::find_if(d.features().begin(),d.features().end(),[&](const auto& f){return f.id==id;});}
ReferenceOption faceAt(const PartDocument& doc,gp_Pnt position,gp_Dir normal){const auto options=doc.referenceOptions();const auto found=std::find_if(options.begin(),options.end(),[&](const auto& o){return o.reference.source==ReferenceSource::BodyFace&&o.geometry.kind==DatumKind::Plane&&std::abs(gp_Vec(position,o.geometry.frame.Location()).Dot(gp_Vec(normal)))<1e-6&&std::abs(o.geometry.frame.Direction().Dot(normal))>0.999;});if(found==options.end()){std::cerr<<"Missing face at "<<position.X()<<","<<position.Y()<<","<<position.Z()<<"; options="<<options.size()<<"\n";for(const auto& o:options)std::cerr<<o.label<<" kind="<<int(o.geometry.kind)<<" pos="<<o.geometry.frame.Location().X()<<","<<o.geometry.frame.Location().Y()<<","<<o.geometry.frame.Location().Z()<<"\n";}check(found!=options.end(),"Expected named face is unavailable");if(found->reference.topologyName.empty())std::cerr<<"Unnamed "<<found->label<<" at "<<position.X()<<","<<position.Y()<<","<<position.Z()<<" features="<<doc.features().size()<<"\n";check(!found->reference.topologyName.empty(),"Generated face has no persistent name");return *found;}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
    auto d=PartDocument::createEmpty();DatumDefinition a;a.method=DatumMethod::PlaneXYZ;a.position={0,0,4};const auto p=d.addReferenceGeometry(a);a.position={0,0,20};a.direction={0,0,-1};const auto q=d.addReferenceGeometry(a);
    const auto mid=make(d,DatumMethod::PlaneMid,{datum(p),datum(q)}),reverse=make(d,DatumMethod::PlaneMid,{datum(q),datum(p)});near(d.resolveReference(datum(mid)).frame.Location().Z(),12);near(d.resolveReference(datum(reverse)).frame.Location().Z(),12);check(d.resolveReference(datum(mid)).frame.Direction().IsEqual(d.resolveReference(datum(reverse)).frame.Direction(),1e-12),"Midplane depends on selection order / normal sign");
    auto edited=feature(d,p);edited.reference.position={0,0,10};d.replaceFeature(edited);near(d.resolveReference(datum(mid)).frame.Location().Z(),15);rejects([&]{make(d,DatumMethod::PlaneMid,{datum(p),datum(p)});});rejects([&]{make(d,DatumMethod::PlaneMid,{datum(p),plane(2)});});make(d,DatumMethod::PlaneOffset,{datum(p)},0);
    GeometryReference axis;axis.source=ReferenceSource::BaseAxis;axis.index=0;const auto perpendicular=make(d,DatumMethod::PlaneNormalToAxis,{axis,{}});near(d.resolveReference(datum(perpendicular)).frame.Direction().X(),1);
    auto box=PartDocument::createBox({20,30,40});const auto top=faceAt(box,{0,0,40},{0,0,1});const auto offset=make(box,DatumMethod::PlaneOffset,{top.reference},5);auto boxEdit=box.features()[0];boxEdit.box.height=60;box.replaceFeature(boxEdit);near(box.resolveReference(datum(offset)).frame.Location().Z(),65);
    const auto upper=faceAt(box,{0,0,60},{0,0,1}),lower=faceAt(box,{0,0,0},{0,0,1});const auto middle=make(box,DatumMethod::PlaneMid,{upper.reference,lower.reference});near(box.resolveReference(datum(middle)).frame.Location().Z(),30);
    auto attached=box.sketchOnFace(upper.reference.index);attached.entities={{EntityKind::Circle,{0,0},{},2,"point-guide"}};const auto attachedId=box.addSketch(attached);boxEdit=box.features()[0];boxEdit.box.height=80;box.replaceFeature(boxEdit);near(box.resolveReference(datum(middle)).frame.Location().Z(),40);near(sketchAxes(feature(box,attachedId).sketch).Location().Z(),80);
    QTemporaryDir dir;const auto path=dir.filePath("named-planes.thepart");box.save(path);box=PartDocument::load(path);boxEdit=box.features()[0];boxEdit.box.height=90;box.replaceFeature(boxEdit);near(box.resolveReference(datum(offset)).frame.Location().Z(),95);near(box.resolveReference(datum(middle)).frame.Location().Z(),45);
    auto prism=PartDocument::createEmpty();Sketch profile;profile.entities={{EntityKind::Rectangle,{-20,-15},{20,15},1,"outline"}};const auto sid=prism.addSketch(profile);const auto boss=prism.addExtrude(sid,{"outline"},20,Direction::Positive);const auto cap=faceAt(prism,{0,0,20},{0,0,1});const auto capPlane=make(prism,DatumMethod::PlaneOffset,{cap.reference},3);auto bossEdit=feature(prism,boss);bossEdit.length=35;prism.replaceFeature(bossEdit);near(prism.resolveReference(datum(capPlane)).frame.Location().Z(),38);
    auto round=PartDocument::createEmpty();Sketch circle;circle.entities={{EntityKind::Circle,{0,0},{},5,"round"}};const auto circleId=round.addSketch(circle);round.addExtrude(circleId,{"round"},20,Direction::Positive);auto options=round.referenceOptions();const auto cylinder=std::find_if(options.begin(),options.end(),[](const auto& o){return o.geometry.cylinderRadius>0;});check(cylinder!=options.end(),"Cylinder provenance missing");const auto tangent=make(round,DatumMethod::PlaneTangentParallel,{cylinder->reference,plane(2)},1);near(round.resolveReference(datum(tangent)).frame.Location().X(),5);
    DatumDefinition point;point.position={5,0,4};const auto pointId=round.addReferenceGeometry(point);make(round,DatumMethod::PlaneTangentAtPoint,{cylinder->reference,datum(pointId)});rejects([&]{make(round,DatumMethod::PlaneTangentAtPoint,{cylinder->reference,{}});});rejects([&]{make(round,DatumMethod::PlaneTangentParallel,{cylinder->reference,plane(0)});});
    // Edit both driving references in an independent cylinder without a pinned tangent point.
    auto radiusModel=round.beforeFeature(pointId);auto radius=feature(radiusModel,circleId);radius.sketch.entities[0].radius=8;radiusModel.replaceFeature(radius);near(radiusModel.resolveReference(datum(tangent)).frame.Location().X(),8);radiusModel.save(path);radiusModel=PartDocument::load(path);radius=feature(radiusModel,circleId);radius.sketch.entities[0].radius=9;radiusModel.replaceFeature(radius);near(radiusModel.resolveReference(datum(tangent)).frame.Location().X(),9);
    // Boolean history: base top survives a round hole, then becomes two faces.
    auto cut=PartDocument::createBox({40,30,20});Sketch cutter;cutter.entities={{EntityKind::Circle,{20,15},{},3,"tool"}};const auto toolId=cut.addSketch(cutter);cut.addCut(toolId,{"tool"},1,true,Direction::Positive);const auto supported=faceAt(cut,{0,0,20},{0,0,1});const auto planeId=make(cut,DatumMethod::PlaneOffset,{supported.reference},2);auto base=cut.features()[0];base.box.height=30;cut.replaceFeature(base);near(cut.resolveReference(datum(planeId)).frame.Location().Z(),32);
    auto tool=feature(cut,toolId);tool.sketch.entities[0]={EntityKind::Rectangle,{18,-5},{22,35},1,"tool"};const auto count=cut.features().size();rejects([&]{cut.replaceFeature(tool);});check(cut.features().size()==count,"Failed topology edit was not transactional");near(cut.resolveReference(datum(planeId)).frame.Location().Z(),32);
    std::cout<<"PASS: midplanes, normal/tangent planes, persistent primitive/prism/Boolean names, face sketches, regeneration, save/reopen and split rejection\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
